float AngleToTarget(Transform self, Transform target)
{
    Vector3 toTarget = (target.position - self.position).normalized;
    float dot = Vector3.Dot(self.forward, toTarget);
    return Mathf.Acos(dot) * Mathf.Rad2Deg;
}
